const lines = require('fs').readFileSync(0, 'utf8').split('\n');
const [r, c] = lines[0].trim().split(/\s+/).map(Number);
const g = [];
for (let i = 0; i < r; i++) g.push(lines[1 + i].trim().split(''));
let count = 0;
for (let i = 0; i < r; i++) {
  for (let j = 0; j < c; j++) {
    if (g[i][j] !== '1') continue;
    count++;
    const stack = [[i, j]];
    g[i][j] = '0';
    while (stack.length) {
      const [x, y] = stack.pop();
      for (const [dx, dy] of [[1,0],[-1,0],[0,1],[0,-1]]) {
        const nx = x + dx, ny = y + dy;
        if (nx >= 0 && ny >= 0 && nx < r && ny < c && g[nx][ny] === '1') {
          g[nx][ny] = '0';
          stack.push([nx, ny]);
        }
      }
    }
  }
}
console.log(count);

